bucket = system.util.jsonDecode(system.util.jsonEncode(value))
unfiltered = []

# extract entries
for entry in bucket:
    if isinstance(entry, dict):
        unfiltered.append(entry["when"])
        if isinstance(entry["what"], list):
            for SubEntry in entry["what"]:
                unfiltered.append(SubEntry)
        else:
            unfiltered.append(entry["what"])
    else:
        unfiltered.append(entry)

return [i for i in unfiltered if isinstance(i, str)]

bucket = system.util.jsonDecode(system.util.jsonEncode(value))
unprocessed = []

# extract entries
for entry in bucket:
    if isinstance(entry, dict):
        if self.session.custom.when[entry["when"]]:
            if isinstance(entry["what"], list):
                for SubEntry in entry["what"]:
                    unprocessed.append(SubEntry)
            else:
                unprocessed.append(entry["what"])
    else:
        unprocessed.append(entry)

return sum([self.session.custom.what[i] if isinstance(i, str) else i for i in unprocessed])

